let _firebasePromise = null;
function loadFirebase() {
  if (!_firebasePromise) {
    _firebasePromise = (async () => {
      const appMod = await import("firebase/app");
      const fsMod = await import("firebase/firestore");
      const firebaseConfig = {
        apiKey: "AIzaSyCx9bEMWB8hx19jq15kV6RIyXXyod7fdZg",
        authDomain: "chat-van.firebaseapp.com",
        projectId: "chat-van",
        storageBucket: "chat-van.firebasestorage.app",
        messagingSenderId: "383286816110",
        appId: "1:383286816110:web:57a77594717f95b004657f",
      };
      const app = appMod.getApps().length ? appMod.getApp() : appMod.initializeApp(firebaseConfig);
      const db = fsMod.getFirestore(app);
      return { db, ...fsMod };
    })();
  }
  return _firebasePromise;
}

function CoPilotChat({ onClose }) {
  const [name, setName] = useState("");
  const [joined, setJoined] = useState(false);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [showEmoji, setShowEmoji] = useState(false);
  const [fbReady, setFbReady] = useState(false);
  const [fbError, setFbError] = useState(false);
  const fbRef = useRef({});
  const listRef = useRef(null);

  useEffect(() => {
    if (!joined) return;
    let unsub;
    let cancelled = false;
    (async () => {
      try {
        const fb = await loadFirebase();
        fbRef.current = fb;
        if (cancelled) return;
        setFbReady(true);
        const q = fb.query(fb.collection(fb.db, "copilot-messages"), fb.orderBy("createdAt", "asc"), fb.limit(200));
        unsub = fb.onSnapshot(q, (snap) => {
          setMessages(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
        });
      } catch (err) {
        console.error("Co-pilot chat unavailable:", err);
        if (!cancelled) setFbError(true);
      }
    })();
    return () => { cancelled = true; if (unsub) unsub(); };
  }, [joined]);

  useEffect(() => {
    if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
  }, [messages]);

  async function sendMessage(content) {
    const trimmed = content.trim();
    if (!trimmed || !fbReady) return;
    const { db, collection, addDoc, serverTimestamp } = fbRef.current;
    const isGif = /\.gif(\?.*)?$/i.test(trimmed) || /giphy\.com|tenor\.com/i.test(trimmed);
    try {
      await addDoc(collection(db, "copilot-messages"), {
        name,
        text: isGif ? null : trimmed,
        gifUrl: isGif ? trimmed : null,
        createdAt: serverTimestamp(),
      });
      setText("");
    } catch (err) {
      console.error("Could not send message:", err);
    }
  }

  const EMOJIS = ["😀", "😂", "❤️", "🔥", "🎶", "🙌", "👍", "😍", "🚐", "🌿"];

  return (
    <div className="chat-overlay fade-in">
      {!joined ? (
        <div className="chat-join-card">
          <button className="detail-close chat-close" onClick={onClose} aria-label="close">
            <X size={20} />
          </button>
          <div className="eyebrow eyebrow-center">CO-PILOT CHAT</div>
          <h2 className="page-title center" style={{ fontSize: 24 }}>Μπες στη διαδρομή</h2>
          <input
            className="chat-name-input"
            placeholder="Το όνομά σου"
            value={name}
            onChange={(e) => setName(e.target.value)}
            maxLength={24}
          />
          <button className="pill-btn" disabled={!name.trim()} onClick={() => setJoined(true)}>
            Σύνδεση
          </button>
        </div>
      ) : (
        <div className="chat-panel">
          <div className="chat-header">
            <div className="chat-header-title">Co-pilot Chat</div>
            <button className="icon-btn" onClick={onClose} aria-label="close">
              <X size={18} />
            </button>
          </div>
          {fbError ? (
            <div className="chat-error">Το chat δεν είναι διαθέσιμο αυτή τη στιγμή.</div>
          ) : (
            <>
              <div className="chat-messages" ref={listRef}>
                {messages.map((m) => (
                  <div key={m.id} className={`chat-msg ${m.name === name ? "chat-msg-mine" : ""}`}>
                    <div className="chat-msg-name">{m.name}</div>
                    {m.gifUrl ? (
                      <img src={m.gifUrl} alt="gif" className="chat-msg-gif" />
                    ) : (
                      <div className="chat-msg-text">{m.text}</div>
                    )}
                  </div>
                ))}
              </div>
              {showEmoji && (
                <div className="chat-emoji-row">
                  {EMOJIS.map((e) => (
                    <button key={e} type="button" className="chat-emoji-btn" onClick={() => setText((t) => t + e)}>
                      {e}
                    </button>
                  ))}
                </div>
              )}
              <form className="chat-input-row" onSubmit={(e) => { e.preventDefault(); sendMessage(text); }}>
                <button type="button" className="icon-btn" onClick={() => setShowEmoji((s) => !s)} aria-label="emoji">
                  <Smile size={18} />
                </button>
                <input
                  className="chat-text-input"
                  placeholder="Γράψε μήνυμα ή link GIF..."
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                />
                <button type="submit" className="chat-send-btn">Send</button>
              </form>
            </>
          )}
        </div>
      )}
    </div>
  );
}

