const GREECE_BOUNDS = { latMin: 34.8, latMax: 41.9, lonMin: 19.2, lonMax: 28.3 };
function projectLatLon(lat, lon) {
  const left = ((lon - GREECE_BOUNDS.lonMin) / (GREECE_BOUNDS.lonMax - GREECE_BOUNDS.lonMin)) * 100;
  const top = ((GREECE_BOUNDS.latMax - lat) / (GREECE_BOUNDS.latMax - GREECE_BOUNDS.latMin)) * 100;
  return { left: Math.min(96, Math.max(4, left)), top: Math.min(94, Math.max(6, top)) };
}

