function RouteMapClickCatcher({ onPick }) {
  useMapEvents({ click(e) { onPick(e.latlng.lat, e.latlng.lng); } });
  return null;
}

// FIX: this map mounts inside a tab/view that is itself swapped in after the
// fact (Pick the Route / Postcards location picker) rather than being on the
// page from first paint. Leaflet measures its tile grid against the
// container's size at the moment it mounts — if that moment lands before the
// surrounding layout has settled (tab transition, fonts/images still
// loading), it locks in the wrong size, and zooming afterwards then renders
// against stale dimensions: tiles misaligned, the zoomed-in area not where
// you clicked, blank/grey tile gaps. invalidateSize() makes Leaflet
// re-measure and redraw against the real, current container size. Same
// pattern already used by FitRouteBounds below for the animated journey/
// ferry maps — this just brings the interactive picker map in line with it.
function MapInvalidateOnMount() {
  const map = useMap();
  useEffect(() => {
    map.invalidateSize();
    const t1 = setTimeout(() => map.invalidateSize(), 150);
    const t2 = setTimeout(() => map.invalidateSize(), 500);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, [map]);
  return null;
}

